				Server: ServerConfig{
					Protocol: HTTPS,
					CertFile: "foo.pem",
					CertKey:  "./testdata/ssl_key.pem",
				},
			},
			wantErrMsg: "cannot find TLS server.cert_file at \"foo.pem\"",
		},
		{
			name: "https: missing key_file",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/ssl_cert.pem",
					CertKey:  "bar.pem",
				},
			},
			wantErrMsg: "cannot find TLS server.cert_key at \"bar.pem\"",
		},
